        clauses = []
        for _ in range(n):
            clause = [random.randint(1, n), -random.randint(1, n)]
            clauses.append(clause)
        return clauses

    def tseitin_resolution_tree(cnf):
        literals = set()
        for clause in cnf:
            literals.update(abs(lit) for lit in clause)

        nodes = {lit: [] for lit in literals}

        for clause in cnf:
            if len(clause) == 1:
                literal = clause[0]
                neg_literal = -literal
                nodes[literal].append(neg_literal)
                nodes[neg_literal].append(literal)
            else:
                new_var = max(literals) + 1
                literals.add(new_var)
                for lit in clause:
                    nodes[lit].append(-new_var)
                    nodes[-new_var].append(lit)
                for i in range(len(clause)):
                    for j in range(i + 1, len(clause)):
                        neg_lit1 = -clause[i]
                        neg_lit2 = -clause[j]
                        nodes[neg_lit1].append(neg_lit2)
                        nodes[neg_lit2].append(neg_lit1)

        return nodes

    def algebraic_k_theory_rank(tree):
        visited = set()
        rank = 0

        def dfs(node, parent):
            nonlocal rank
            if node in visited:
                return
            visited.add(node)
            for neighbor in tree[node]:
                if neighbor != parent:
                    dfs(neighbor, node)
                    rank += 1

        for node in tree:
            if node not in visited:
                dfs(node, None)

        return rank

    n = random.randint(5, 40)
    cnf = generate_cnf(n)
    tree = tseitin_resolution_tree(cnf)
